CAT = "aevoRahmen"; SEG = "RAH"
# Handlungsfeld 1 (Rahmenplan 1.2, 1.5): rechtlicher Rahmen, Eignung von Ausbildungsstätte und
# Ausbildungspersonal, zuständige Stellen, Grundregeln des JArbSchG.
Q = [
("Wer darf nach dem BBiG Auszubildende selbst ausbilden?",
 "Persönlich und fachlich Geeignete", ["Nur fachlich geeignete Personen", "Personen mit Meisterprüfung", "Alle erfahrenen Beschäftigten ab 24 Jahren"],
 "Einstellen darf nur, wer persönlich geeignet ist; ausbilden darf nur, wer persönlich und fachlich geeignet ist (§ 28 Abs. 1 BBiG)."),
("Wann ist eine Person nach § 29 BBiG insbesondere persönlich nicht geeignet?",
 "Sie darf Jugendliche nicht beschäftigen", ["Sie hat keinen Meistertitel", "Sie arbeitet im Betrieb nur noch in Teilzeit", "Sie ist jünger als 25 Jahre"],
 "Persönlich ungeeignet ist, wer Kinder und Jugendliche nicht beschäftigen darf oder wiederholt oder schwer gegen das BBiG verstoßen hat (§ 29 BBiG)."),
("Was gehört neben den beruflichen Kenntnissen zur fachlichen Eignung eines Ausbilders?",
 "Berufs- und arbeitspädagogische Eignung", ["Ein abgeschlossenes Studium", "Eine Mitgliedschaft in der zuständigen Kammer", "Fünf Jahre Führungserfahrung"],
 "Fachlich geeignet ist, wer die beruflichen sowie die berufs- und arbeitspädagogischen Fertigkeiten, Kenntnisse und Fähigkeiten besitzt (§ 30 Abs. 1 BBiG)."),
("Für welchen Bereich verlangt die Ausbilder-Eignungsverordnung keinen gesonderten Nachweis?",
 "Für die freien Berufe", ["Für das Handwerk", "Für Industrie und Handel", "Für die Landwirtschaft"],
 "§ 1 AEVO nimmt die Ausbildung im Bereich der Angehörigen der freien Berufe aus, etwa in Arzt- oder Anwaltspraxen."),
("Eine Tischlermeisterin will in ihrem Betrieb ausbilden. Was gilt für ihre berufs- und arbeitspädagogische Eignung?",
 "Die Meisterprüfung reicht als Nachweis", ["Sie braucht zusätzlich die AEVO-Prüfung", "Sie muss einen Lehrgang belegen", "Die Berufsschule muss sie bestätigen"],
 "Wer die Eignung in einer Meister- oder anderen Fortbildungsprüfung nachgewiesen hat, gilt als berufs- und arbeitspädagogisch geeignet (§ 6 Abs. 2 AEVO)."),
("Ein Betrieb kann nicht alle Inhalte des Ausbildungsberufs selbst vermitteln. Wann gilt er dennoch als geeignet?",
 "Wenn externe Maßnahmen das abdecken", ["Wenn der Azubi schriftlich zustimmt", "Wenn die Berufsschule es übernimmt", "Wenn die Probezeit länger dauert"],
 "Fehlende Inhalte können durch Ausbildungsmaßnahmen außerhalb der Ausbildungsstätte vermittelt werden (§ 27 Abs. 2 BBiG), etwa im Verbund oder überbetrieblich."),
("Was verlangt § 27 BBiG zur Zahl der Auszubildenden in einem Betrieb?",
 "Angemessenes Verhältnis zu Fachkräften", ["Höchstens zwei Azubis je Betrieb", "Mindestens fünf Fachkräfte je Ausbildungsplatz", "Höchstens ein Azubi je Ausbilder"],
 "Die Zahl der Auszubildenden muss in angemessenem Verhältnis zu den Ausbildungsplätzen oder Fachkräften stehen (§ 27 Abs. 1 Nr. 2 BBiG). Feste Zahlen nennt das Gesetz nicht."),
("Wer überwacht, ob die Eignung von Ausbildungsstätte und Ausbildungspersonal vorliegt?",
 "Die zuständige Stelle", ["Die Berufsschule", "Die Agentur für Arbeit", "Der Betriebsrat"],
 "Die zuständige Stelle, etwa die IHK oder HWK, wacht über die Eignung (§ 32 Abs. 1 BBiG) und bestellt dafür Ausbildungsberater (§ 76 BBiG)."),
("Wer kann das Einstellen und Ausbilden untersagen, wenn die persönliche oder fachliche Eignung fehlt?",
 "Die nach Landesrecht zuständige Behörde", ["Die Industrie- und Handelskammer", "Das Bundesinstitut für Berufsbildung (BIBB)", "Der Prüfungsausschuss"],
 "Die Untersagung spricht die nach Landesrecht zuständige Behörde aus (§ 33 BBiG). Die Kammer stellt Mängel fest und meldet sie dieser Behörde."),
("Die Kammer stellt einen behebbaren Eignungsmangel fest, Auszubildende sind nicht gefährdet. Was folgt zuerst?",
 "Eine Frist zur Beseitigung", ["Ein sofortiges Ausbildungsverbot", "Die Löschung des Vertrags", "Ein Bußgeld ohne Anhörung"],
 "Ist der Mangel zu beheben und keine Gefährdung zu erwarten, fordert die zuständige Stelle zur Beseitigung innerhalb einer Frist auf (§ 32 Abs. 2 BBiG)."),
("Ein Kfz-Handwerksbetrieb bildet Kfz-Mechatroniker aus. Wer ist die zuständige Stelle?",
 "Die Handwerkskammer", ["Die Industrie- und Handelskammer", "Die Landwirtschaftskammer", "Die Agentur für Arbeit"],
 "Für Berufe der Handwerksordnung ist die Handwerkskammer zuständige Stelle (§ 71 Abs. 1 BBiG)."),
("Wer ist zuständige Stelle für die Ausbildung zur Steuerfachangestellten?",
 "Die Steuerberaterkammer", ["Die Industrie- und Handelskammer", "Das Finanzamt", "Die Handwerkskammer"],
 "Für Fachangestellte im Bereich Wirtschaftsprüfung und Steuerberatung sind die Wirtschaftsprüfer- und Steuerberaterkammern zuständig (§ 71 Abs. 5 BBiG)."),
("Wer ist Jugendlicher im Sinne des Jugendarbeitsschutzgesetzes?",
 "Wer 15, aber noch nicht 18 ist", ["Wer 14, aber noch nicht 18 ist", "Wer 16, aber noch nicht 21 ist", "Wer noch nicht 25 Jahre alt ist"],
 "Kind ist, wer noch nicht 15 ist; Jugendlicher, wer 15, aber noch nicht 18 ist (§ 2 JArbSchG)."),
("Wie lange darf eine 16-jährige Auszubildende nach dem JArbSchG höchstens arbeiten?",
 "8 Stunden am Tag, 40 pro Woche", ["8 Stunden am Tag, 45 pro Woche", "9 Stunden am Tag, 40 pro Woche", "10 Stunden am Tag, 48 pro Woche"],
 "Jugendliche dürfen nicht mehr als acht Stunden täglich und 40 Stunden wöchentlich beschäftigt werden (§ 8 Abs. 1 JArbSchG). Ist ein Tag verkürzt, sind an den übrigen Werktagen 8,5 Stunden möglich."),
("Für welche Ausbildung gilt das Berufsbildungsgesetz nicht?",
 "Für Beamte im Vorbereitungsdienst", ["Für kaufmännische Berufe", "Für Berufe in Arztpraxen", "Für Berufe im Hotel- und Gastgewerbe"],
 "Das BBiG gilt nicht für die Berufsbildung in einem öffentlich-rechtlichen Dienstverhältnis, an Hochschulen und auf Kauffahrteischiffen (§ 3 Abs. 2 BBiG)."),
("Ein Ausbilder wurde vor zwei Jahren rechtskräftig wegen eines Verbrechens zu drei Jahren Freiheitsstrafe verurteilt. Was gilt?",
 "Er darf keine Jugendlichen ausbilden", ["Er darf es mit Zustimmung der Eltern", "Er darf es, wenn ein Kollege dabei ist", "Er darf es nach der Probezeit"],
 "Wer wegen eines Verbrechens zu mindestens zwei Jahren verurteilt wurde, darf Jugendliche nicht beschäftigen, beaufsichtigen oder ausbilden, bis fünf Jahre seit Rechtskraft verstrichen sind (§ 25 JArbSchG)."),
]
